export const SOUND_NAMES=['laser','sword-swing','sword-hit','atomic','punch','impact'];
export class CombatAudio {
 constructor({contextFactory=()=>new (window.AudioContext||window.webkitAudioContext)(),fetcher=fetch}={}){this.contextFactory=contextFactory;this.fetcher=fetcher;this.enabled=true;this.buffers=new Map();this.loading=null;this.cursor=0;this.match='';this.last=new Map();this.voices=0;}
 async unlock(){if(!this.enabled)return;try{if(!this.ctx){this.ctx=this.contextFactory();this.master=this.ctx.createGain();this.master.gain.value=.32;const compressor=this.ctx.createDynamicsCompressor();this.master.connect(compressor);compressor.connect(this.ctx.destination);}await this.ctx.resume();if(!this.loading)this.loading=Promise.all(SOUND_NAMES.map(async name=>{try{const r=await this.fetcher('/audio/'+name+'.wav');if(r.ok)this.buffers.set(name,await this.ctx.decodeAudioData(await r.arrayBuffer()));}catch{}}));await this.loading;}catch{}}
 setEnabled(value){this.enabled=value;if(this.master)this.master.gain.value=value?.32:0;if(value)this.unlock();}
 play(name,{gain=1,pan=0}={}){if(!this.enabled||!this.ctx||this.ctx.state==='suspended'||!this.buffers.has(name)||this.voices>=8)return false;const now=this.ctx.currentTime;if(now-(this.last.get(name)??-10)<.045)return false;this.last.set(name,now);const source=this.ctx.createBufferSource(),volume=this.ctx.createGain();source.buffer=this.buffers.get(name);volume.gain.value=gain;source.connect(volume);if(this.ctx.createStereoPanner){const p=this.ctx.createStereoPanner();p.pan.value=Math.max(-.7,Math.min(.7,pan));volume.connect(p);p.connect(this.master);}else volume.connect(this.master);this.voices++;source.onended=()=>{this.voices--;source.disconnect();volume.disconnect();};source.start(now+(name==='sword-hit'?.035:0));return true;}
 consume(game,match){if(this.match!==match){this.match=match;this.cursor=0;}const events=game.soundEvents||[];for(const e of events){if(e.id<=this.cursor)continue;this.cursor=e.id;const distance=Math.abs(e.x-game.player.x);this.play(e.kind,{gain:e.owner===game.player.id?1:Math.max(.12,.65-distance/1800),pan:(e.x-game.player.x)/900});}}
}
